BILLS.forEach(b => {
  b.hours = b.v * 240 / b.wage;
  b.eq = b.v * W2026 / b.wage;
  b.wear = b.crit.reduce((a, c) => a + c, 0) * 5;
  b.grade = b.wear <= 10 ? "EBC" : b.wear <= 30 ? "MBC" : b.wear <= 50 ? "BC" : b.wear <= 75 ? "RC" : "MC";
  b.year = +b.date.slice(0, 4);
  b.short = `${b.den} · ${b.year}`;
});
